-- =================================================================
-- ZENIT - PURGA DEFINITIVA DE PLACEHOLDERS ("IMAGEN NO DISPONIBLE")
-- Y CORTES A GRANEL REPETITIVOS EN SUPABASE
-- 
-- Instrucciones:
-- 1. Copiá todo este contenido (es un script ligero de menos de 10 KB).
-- 2. Pegalo en Supabase > SQL Editor y hacé clic en "RUN".
-- 3. Tarda menos de 1 segundo y limpia tu base a 4.073 productos 100% verificados.
-- =================================================================

-- Paso 1: Eliminar fotos genéricas de stock de Unsplash y registros sin URL
DELETE FROM public.foods 
WHERE image LIKE '%unsplash.com%' 
   OR image IS NULL 
   OR image = '';

-- Paso 2: Eliminar productos con código de balanza/granel interno sin empaque de estudio
DELETE FROM public.foods 
WHERE name ILIKE '%sin atributo%' 
   OR name ILIKE '%zona 1 x kg%' 
   OR name ILIKE '%zona 2 x kg%';

